package com.halo.sdk.runtime.embodiment

/**
 * Represents the semantic lifecycle of a physical execution request across the embodiment boundary.
 * 
 * Intents do not instantly complete. They transition through these states.
 */
enum class ExecutionStatus {
    /** The intent has been generated by the cognitive runtime. */
    CREATED,
    /** The intent has been dispatched to the transport layer. */
    DISPATCHED,
    /** The physical embodiment received the intent and accepted it for resolution. */
    ACCEPTED,
    /** The physical embodiment received the intent but rejected it immediately (e.g. invalid). */
    REJECTED,
    /** The intent is being resolved into a sequence of physical capabilities. */
    RESOLVING,
    /** The safety supervisor authorized the resolved physical action. */
    AUTHORIZED,
    /** The safety supervisor denied the action (e.g. obstacle detected). */
    DENIED,
    /** The hardware is currently executing the physical action. */
    EXECUTING,
    /** The physical action was successfully completed in the real world. */
    SUCCEEDED,
    /** The physical action was dispatched but success/failure could not be confirmed. */
    UNCONFIRMED,
    /** The physical action failed during execution (e.g. motor fault). */
    FAILED,
    /** The physical action was aborted mid-execution (e.g. emergency stop). */
    ABORTED
}
